from collections import Counter

def hamming_distance(s1, s2):
    """Calculate the Hamming distance."""
    return sum(bin(x ^ y).count('1') for x, y in zip(s1, s2))

def normalized_hamming_distance(cipher, key_size):
    """Calculate normalized Hamming distance for a given key size."""
    chunks = [cipher[i:i + key_size] for i in range(0, len(cipher), key_size)]
    pairs = [(chunks[i], chunks[i + 1]) for i in range(len(chunks) - 1)]
    distances = [hamming_distance(pair[0], pair[1]) / key_size for pair in pairs if len(pair[0]) == len(pair[1])]
    return sum(distances) / len(distances) if distances else None

def analyze_key_size(cipher):
    """Return the most probable key size based on normalized hamming distance."""
    candidates = {}
    for key_size in range(1, 41): # Test key sizes from 1 to 40
        score = normalized_hamming_distance(cipher, key_size)
        if score is not None:
            candidates[key_size] = score

    # Sort the candidates by score (lower is better)
    return sorted(candidates, key=candidates.get)

